import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, ActivatedRoute } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../core/services/api.service';

@Component({
  selector: 'app-destination-list',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header">
      <div class="container">
        <h1>Điểm Đến Du Lịch</h1>
        <p>Khám phá những địa điểm du lịch đẹp nhất Việt Nam</p>
      </div>
    </div>

    <section class="section">
      <div class="container">
        <div class="filters-bar">
          <div class="filter-search">
            <span class="material-icons">search</span>
            <input type="text" [(ngModel)]="filters.search" (ngModelChange)="onSearchChange()" placeholder="Tìm kiếm địa điểm..." class="search-input">
          </div>
          <div class="filter-group">
            <select class="form-control" [(ngModel)]="filters.category" (change)="loadDestinations()">
              <option value="">Tất cả loại hình</option>
              <option *ngFor="let c of categories" [value]="c.slug">{{ c.name }}</option>
            </select>
            <select class="form-control" [(ngModel)]="filters.region" (change)="loadDestinations()">
              <option value="">Tất cả vùng miền</option>
              <option value="NORTH">Miền Bắc</option>
              <option value="CENTRAL">Miền Trung</option>
              <option value="SOUTH">Miền Nam</option>
            </select>
            <select class="form-control" [(ngModel)]="filters.sort" (change)="loadDestinations()">
              <option value="createdAt">Mới nhất</option>
              <option value="rating">Đánh giá cao</option>
              <option value="reviewCount">Nhiều đánh giá</option>
              <option value="viewCount">Phổ biến</option>
            </select>
          </div>
        </div>

        <div class="loading-spinner" *ngIf="loading">
          <div class="spinner"></div>
        </div>

        <div class="grid grid-4" *ngIf="!loading">
          <a *ngFor="let d of destinations" [routerLink]="['/destinations', d.slug]" class="card dest-card fade-in">
            <div class="card-image">
              <img [src]="d.images[0]?.url || 'https://picsum.photos/seed/' + d.slug + '/400/300'" [alt]="d.name">
              <span class="badge badge-warning card-badge" *ngIf="d.isFeatured">Nổi bật</span>
            </div>
            <div class="card-body">
              <div class="card-category">{{ d.category?.name }}</div>
              <h3>{{ d.name }}</h3>
              <p class="location"><span class="material-icons">location_on</span> {{ d.province?.name }}</p>
              <p class="short-desc">{{ d.shortDescription }}</p>
              <div class="card-footer">
                <div class="rating">
                  <span class="score">{{ d.rating }}</span>
                  <span class="stars">★★★★★</span>
                  <span class="count">({{ d.reviewCount }})</span>
                </div>
                <span class="cost">{{ d.estimatedCost }}</span>
              </div>
            </div>
          </a>
        </div>

        <div class="empty-state" *ngIf="!loading && destinations.length === 0">
          <span class="material-icons">search_off</span>
          <h3>Không tìm thấy địa điểm nào</h3>
          <p>Thử thay đổi bộ lọc hoặc từ khóa tìm kiếm</p>
        </div>

        <div class="pagination" *ngIf="!loading && pagination.totalPages > 1">
          <button [disabled]="pagination.page <= 1" (click)="goToPage(pagination.page - 1)">
            <span class="material-icons">chevron_left</span>
          </button>
          <button *ngFor="let p of pageNumbers" [class.active]="p === pagination.page" (click)="goToPage(p)">{{ p }}</button>
          <button [disabled]="pagination.page >= pagination.totalPages" (click)="goToPage(pagination.page + 1)">
            <span class="material-icons">chevron_right</span>
          </button>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .filters-bar {
      display: flex;
      gap: 1rem;
      margin-bottom: 2rem;
      flex-wrap: wrap;
      align-items: center;
    }

    .filter-search {
      flex: 1;
      min-width: 250px;
      position: relative;
      .material-icons { position: absolute; left: 1rem; top: 50%; transform: translateY(-50%); color: var(--gray); }
      .search-input { padding-left: 2.75rem; }
    }

    .filter-group {
      display: flex;
      gap: 0.75rem;
      flex-wrap: wrap;
      select { min-width: 150px; }
    }

    .dest-card {
      text-decoration: none;
      color: inherit;
      display: block;
    }

    .card-image {
      position: relative;
      height: 200px;
      overflow: hidden;
      img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s; }
    }
    .dest-card:hover .card-image img { transform: scale(1.08); }
    .card-badge { position: absolute; top: 12px; right: 12px; }

    .card-category { font-size: 0.75rem; color: var(--primary); font-weight: 600; text-transform: uppercase; margin-bottom: 0.25rem; }
    h3 { font-size: 1rem; margin-bottom: 0.5rem; }

    .location {
      display: flex;
      align-items: center;
      gap: 0.25rem;
      color: var(--gray);
      font-size: 0.875rem;
      margin-bottom: 0.5rem;
      .material-icons { font-size: 1rem; }
    }

    .short-desc {
      color: var(--gray);
      font-size: 0.875rem;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
      margin-bottom: 0.75rem;
    }

    .card-footer {
      display: flex;
      justify-content: space-between;
      align-items: center;
      border-top: 1px solid #f1f5f9;
      padding-top: 0.75rem;
    }

    .cost { font-size: 0.8125rem; color: var(--gray); }
  `]
})
export class DestinationListComponent implements OnInit {
  destinations: any[] = [];
  categories: any[] = [];
  loading = true;
  filters: any = { search: '', category: '', region: '', sort: 'createdAt' };
  pagination: any = { page: 1, limit: 12, total: 0, totalPages: 0 };
  pageNumbers: number[] = [];

  constructor(private api: ApiService, private route: ActivatedRoute) {}

  ngOnInit() {
    this.route.queryParams.subscribe(params => {
      this.filters.search = params['search'] || '';
      this.filters.category = params['category'] || '';
      this.loadCategories();
      this.loadDestinations();
    });
  }

  loadCategories() {
    this.api.getDestinationCategories().subscribe({
      next: (data) => { this.categories = data; }
    });
  }

  loadDestinations() {
    this.loading = true;
    const params = { page: this.pagination.page, limit: 12, ...this.filters };
    Object.keys(params).forEach(k => { if (!params[k]) delete params[k]; });
    this.api.getDestinations(params).subscribe({
      next: (res) => {
        this.destinations = res.data;
        this.pagination = res.pagination;
        this.pageNumbers = Array.from({length: Math.min(5, res.pagination.totalPages)}, (_, i) => i + 1);
        this.loading = false;
      },
      error: () => { this.loading = false; }
    });
  }

  onSearchChange() {
    clearTimeout((this as any).searchTimeout);
    (this as any).searchTimeout = setTimeout(() => this.loadDestinations(), 500);
  }

  goToPage(page: number) {
    this.pagination.page = page;
    this.loadDestinations();
    window.scrollTo({ top: 300, behavior: 'smooth' });
  }
}
